static
void kernel_bicg(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_M; i++)
    s[i] = 0;
  for (i = 0; i < _PB_N; i++)
    {
      q[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_M; j++)
	{
	  s[j] = s[j] + r[i] * A[i][j];
	  q[i] = q[i] + A[i][j] * p[j];
	}
    }
#pragma endscop

#if defined(__riscv_vector)
  // Use RISC-V Vector intrinsics to optimize the inner loop
  int vl;
  __riscv_vsetvl(vl, _PB_M, _PB_M, 1);
  __riscv_vsetvl(vl, _PB_N, _PB_N, 1);

  for (i = 0; i < _PB_M; i++)
    {
      __riscv_vsetvl(vl, _PB_M, _PB_M, 1);
      __riscv_vsetvl(vl, _PB_N, _PB_N, 1);

      __riscv_vfloat32_t v_s = __riscv_vfmul_vv_f32(r[i], A[i], vl);
      __riscv_vfloat32_t v_q = __riscv_vfmul_vv_f32(A[i], p, vl);

      for (j = 0; j < _PB_M; j++)
	{
	  s[j] = __riscv_vfmadd_vv_f32(s[j], v_s, vl);
	  q[i] = __riscv_vfmadd_vv_f32(q[i], v_q, vl);
	}
    }
#endif

}

