void kernel_doitgen(int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

#pragma scop
  for (r = 0; r < _PB_NR; r++)
    for (q = 0; q < _PB_NQ; q++)  {
      for (p = 0; p < _PB_NP; p++)  {
	sum[p] = SCALAR_VAL(0.0);
	for (s = 0; s < _PB_NP; s++)
	  sum[p] += A[r][q][s] * C4[s][p];
      }
      for (p = 0; p < _PB_NP; p++)
	A[r][q][p] = sum[p];
    }
#pragma endscop

#if defined(__riscv_vector)
  // Use RISC-V Vector intrinsics to optimize the inner loop
  for (r = 0; r < _PB_NR; r++)
    for (q = 0; q < _PB_NQ; q++)  {
      // Load C4 into a vector register
      __riscv_vector_load(C4[0], np, np);
      // Load A[r][q][0] into a vector register
      __riscv_vector_load(A[r][q][0], np, np);
      // Perform the dot product of A[r][q][0] and C4
      __riscv_vector_dot_product(A[r][q][0], C4[0], np, np);
      // Store the result back into A[r][q][0]
      __riscv_vector_store(A[r][q][0], np, np);
    }
#endif
}

