static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      for(i = 0; i < _PB_N; i++)
	for (j = 0; j < _PB_N; j++)
	  path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
	    path[i][j] : path[i][k] + path[k][j];
    }
#pragma endscop

  // Optimize using RISC-V Vector intrinsics
  #if defined(__riscv_vector)
  // Load the vector length
  size_t vl = __riscv_vector_length();

  // Initialize the vector mask
  __riscv_vector_mask_t mask = __riscv_vector_mask_init();

  // Load the vector elements
  __riscv_vector_t path_vec = __riscv_vector_load(path, vl);
  __riscv_vector_t path_k_vec = __riscv_vector_load(path[k], vl);
  __riscv_vector_t path_kj_vec = __riscv_vector_load(path[k][j], vl);

  // Compute the minimum values
  __riscv_vector_t min_vec = __riscv_vector_min(path_vec, path_k_vec + path_kj_vec, mask);

  // Store the minimum values
  __riscv_vector_store(path, min_vec, vl);
  #endif
}

