static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++)
	C[i][j] *= beta;
    for (k = 0; k < _PB_NK; k++) {
       for (j = 0; j < _PB_NJ; j++)
	  C[i][j] += alpha * A[i][k] * B[k][j];
    }
  }
#pragma endscop

#if defined(__riscv_vector)
  // Use RISC-V Vector intrinsics to optimize the inner loop
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++)
	C[i][j] *= beta;
    for (k = 0; k < _PB_NK; k++) {
      // Load A[i][k] and B[k][j] into vectors
      __riscv_vector_register v_a = __riscv_vector_load(A[i][k], 1);
      __riscv_vector_register v_b = __riscv_vector_load(B[k][j], 1);
      // Multiply the vectors and accumulate the result
      __riscv_vector_register v_c = __riscv_vector_mul(v_a, v_b);
      __riscv_vector_register v_d = __riscv_vector_add(v_c, C[i][j]);
      // Store the result back into C[i][j]
      __riscv_vector_store(C[i][j], v_d, 1);
    }
  }
#endif

}

