static
void kernel_mvt(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x1[i] = x1[i] + A[i][j] * y_1[j];
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x2[i] = x2[i] + A[j][i] * y_2[j];
#pragma endscop

  // Optimize using RISC-V Vector intrinsics
  #if defined(__riscv_vector)
  // Load vectors
  __riscv_vector_int_t v_x1 = __riscv_vector_load(x1, n);
  __riscv_vector_int_t v_x2 = __riscv_vector_load(x2, n);
  __riscv_vector_int_t v_y_1 = __riscv_vector_load(y_1, n);
  __riscv_vector_int_t v_y_2 = __riscv_vector_load(y_2, n);
  __riscv_vector_int_t v_A = __riscv_vector_load(A, n * n);

  // Compute dot product
  __riscv_vector_int_t v_dot_1 = __riscv_vector_dot_product(v_x1, v_y_1, n);
  __riscv_vector_int_t v_dot_2 = __riscv_vector_dot_product(v_x2, v_y_2, n);

  // Store results
  __riscv_vector_store(x1, v_dot_1, n);
  __riscv_vector_store(x2, v_dot_2, n);
  #endif
}

