static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;
    for (k = 0; k < _PB_M; k++)
      for (j = 0; j <= i; j++)
	{
	  C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k];
	}
  }
#pragma endscop

#if defined(__riscv_vector)
  // Use RISC-V Vector intrinsics to optimize the inner loop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;
    for (k = 0; k < _PB_M; k++)
      for (j = 0; j <= i; j++)
	{
	  // Load vectors from A and B
	  __riscv_vector_load(A[j][k], alpha, B[i][k]);
	  __riscv_vector_load(B[j][k], alpha, A[i][k]);

	  // Multiply and accumulate
	  __riscv_vector_mul(A[j][k], alpha, B[i][k]);
	  __riscv_vector_mul(B[j][k], alpha, A[i][k]);

	  // Add to C
	  __riscv_vector_add(C[i][j], C[i][j], A[j][k]);
	  __riscv_vector_add(C[i][j], C[i][j], B[j][k]);
	}
  }
#endif

}

#include <riscv_vector.h>

static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;
    for (k = 0; k < _PB_M; k++) {
      for (j = 0; j <= i; j++)
        C[i][j] += alpha * A[i][k] * A[j][k];
    }
  }
#pragma endscop

  // Optimize using RISC-V Vector intrinsics
  #if defined(__riscv_vector)
  // Set the vector length
  size_t vl = __riscv_vector_length();

  // Initialize the vector registers
  __riscv_vector_registers_init();

  // Load the alpha and beta values into vector registers
  __riscv_vector_register_load(alpha, vl);
  __riscv_vector_register_load(beta, vl);

  // Loop over the rows of the matrix
  for (i = 0; i < _PB_N; i++) {
    // Load the C[i][j] values into vector registers
    __riscv_vector_register_load(C[i][j], vl);

    // Multiply the C[i][j] values by beta
    __riscv_vector_register_mul(C[i][j], beta, vl);

    // Store the updated C[i][j] values
    __riscv_vector_register_store(C[i][j], vl);

    // Loop over the columns of the matrix
    for (k = 0; k < _PB_M; k++) {
      // Load the A[i][k] and A[j][k] values into vector registers
      __riscv_vector_register_load(A[i][k], vl);
      __riscv_vector_register_load(A[j][k], vl);

      // Multiply the A[i][k] and A[j][k] values by alpha
      __riscv_vector_register_mul(A[i][k], alpha, vl);
      __riscv_vector_register_mul(A[j][k], alpha, vl);

      // Multiply the A[i][k] and A[j][k] values by the corresponding C[i][j] values
      __riscv_vector_register_mul(C[i][j], A[i][k], vl);
      __riscv_vector_register_mul(C[i][j], A[j][k], vl);

      // Add the updated C[i][j] values
      __riscv_vector_register_add(C[i][j], vl);

      // Store the updated C[i][j] values
      __riscv_vector_register_store(C[i][j], vl);
    }
  }
  #endif
}

