static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      x[i] = b[i];
      for (j = 0; j <i; j++)
        x[i] -= L[i][j] * x[j];
      x[i] = x[i] / L[i][i];
    }
#pragma endscop

#if defined(__riscv_vector)
  // Use RISC-V Vector intrinsics to optimize the inner loop
  for (i = 0; i < _PB_N; i++)
    {
      // Load the vector elements of x and L
      __riscv_vector_load_v(x, x[i], 0);
      __riscv_vector_load_v(L, L[i], 0);

      // Compute the dot product of x and L
      __riscv_vector_dot_v(x, L, x[i], 0);

      // Subtract the dot product from x
      __riscv_vector_sub_v(x, x[i], x[i], 0);

      // Divide x by L[i][i]
      __riscv_vector_div_v(x, x[i], L[i][i], 0);
    }
#endif
}

