static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_M; i++)
     for (j = 0; j < _PB_N; j++) {
        for (k = i+1; k < _PB_M; k++)
           B[i][j] += A[k][i] * B[k][j];
        B[i][j] = alpha * B[i][j];
     }
#pragma endscop

#if defined(__riscv_vector)
  // Use RISC-V Vector intrinsics to optimize the inner loop
  for (i = 0; i < _PB_M; i++) {
    for (j = 0; j < _PB_N; j++) {
      // Load the elements of B[i][j] and B[k][j] into vectors
      vfloat32m8_t v_b_i_j = vle32_v_f32m8(B[i][j], 1);
      vfloat32m8_t v_b_k_j = vle32_v_f32m8(B[k][j], 1);

      // Compute the dot product of A[k][i] and B[k][j]
      vfloat32m8_t v_dot = vfmul_vv_f32m8(v_b_i_j, v_b_k_j, 1);

      // Add the dot product to B[i][j]
      v_b_i_j = vfadd_vv_f32m8(v_b_i_j, v_dot, 1);

      // Store the result back to B[i][j]
      vse32_v_f32m8(B[i][j], v_b_i_j, 1);
    }
  }
#endif
}
